# -*- coding: utf-8 -*-
import re
p='src/lalka-2/work/chapter-01/scaffold.txt'
t={205:'— Пройдисвіт<sup>591</sup>!... — прошепотів, показуючи на двері.',206:'— Ви його знаєте?...',207:'Ба!...',208:'— Отже, — говорила баронеса в другій кімнаті, — нехай пан віднесе до костелу Святого Хреста<sup>592</sup> ті дев’ять рублів на три меси<sup>593</sup>, щоб Бог напоумив його... Ні, — додала за мить трохи зміненим голосом.',209:'— Нехай буде одна меса за нього, а дві — за душу моєї нещасної дівчинки.',210:'Її слова перервав тихий схлип.',211:'— Заспокойтеся, пані!... — лагідно втішав<sup>594</sup> її Марушевич.',212:'— Ідіть уже, ідіть... — відповіла вона.',213:'Раптом двері вітальні відчинилися, і на порозі мов укопаний став Марушевич; за ним я побачив жовтувате обличчя й почервонілі очі пані баронеси. Ми з управителем підвелися зі стільців.',214:'Марушевич відступив углиб другої кімнати й, очевидно, вийшов іншими дверима, а пані баронеса гнівно гукнула:',215:'— Марисю!... Марисю!...',216:'Убігла дівчина в такому самому білому чепчику, як і раніше, у темній сукні й білому фартусі. В такому вбранні вона скидалася б на доглядальницю, якби в її очах не було стільки іскор.',217:'— Як ти могла впустити сюди цих панів? — спитала її баронеса.',218:'— Та пані ж веліла запросити...',219:'— Дурепо... геть!... — прошипіла баронеса. Потім обернулася до нас:',220:'— Чого вам треба, пане Вірський?',221:'— Пан Ржецький — повірений власника дому, — відповів управитель.',222:'— А, а!... Добре... — промовила баронеса, поволі входячи до вітальні й не запрошуючи нас сісти. Портрет цієї дами: чорна сукня, жовтувате обличчя, синюваті губи, почервонілі від сліз очі й гладко зачесане волосся. Вона схрестила руки на грудях, наче Наполеон І, і, дивлячись на мене, сказала:',223:'— А, а, а!... То ви, здається, повірений пана Вокульського... Чи не так?... Передайте йому, що або я виїду з цього помешкання, за яке дуже справно плачу йому сімсот рублів, правда ж, пане Вірський?...',224:'Управитель уклонився.'}
lines=open(p,encoding='utf-8').read().splitlines(); i=-1; out=[]
